using System.Collections.Generic; using UnityEngine;
namespace Demo.Inventory { public sealed class InventoryPanel:MonoBehaviour { [SerializeField] Transform content; [SerializeField] InventoryItemView prefab; [SerializeField] ItemDetailPanel detail; readonly List<InventoryItemView> views=new(); InventoryService service; ItemCategory? category; void OnEnable(){service=InventoryRuntime.Instance.Service;if(service==null)return;service.OnChanged+=Refresh;Refresh();}void OnDisable(){if(service!=null)service.OnChanged-=Refresh;}public async void Refresh(){foreach(var v in views){v.Clear();Destroy(v.gameObject);}views.Clear();if(service==null)return;foreach(var s in service.GetOrdered(category)){var d=service.GetDefinition(s.itemId);var v=Instantiate(prefab,content);views.Add(v);await v.BindAsync(s,d,detail.Show,OnDrop);if(!this||!isActiveAndEnabled)return;}}void OnDrop(int from,int to){if(from!=to)service.MoveItem(from,to);}public void ShowCategory(int i){category=i<0?null:(ItemCategory?)i;Refresh();}}}
